components.draw:
const pal = ['blue', 'orange', 'green', 'purple'];
return [
  hline(0, { color: 'gray', opacity: 0.4 }), vline(0, { color: 'gray', opacity: 0.4 }),
  ...state.keys.map((k, i) => arrow(0, 0, k[0], k[1], { color: pal[i], opacity: 0.6 })),
  arrow(0, 0, state.q[0], state.q[1], { color: 'red', width: 3 }),
  points(state.keys, { id: 'k', draggable: true, colors: pal, r: 8 }),
  point(state.q[0], state.q[1], { id: 'q', draggable: true, color: 'red', r: 9 }),
  text(state.q[0], state.q[1] + 0.25, 'q', { color: 'red' })
];

const w = softmax(state.keys.map((k) => dot(state.q, k) / Math.sqrt(2)), state.temp);
const o = state.vals.reduce((acc, v, i) => add(acc, scale(v, w[i])), [0, 0]);
return [
  ...state.vals.map((v, i) => line([o, v], { color: 'gray', opacity: 0.2 + 0.8 * w[i], width: 1 + 6 * w[i] })),
  points(state.vals, { colors: ['blue', 'orange', 'green', 'purple'], r: 8 }),
  point(o[0], o[1], { color: 'red', r: 9 })
];
